43	function endTurn(
44		state: ISessionState,
45		turnId: string,
46		turnState: TurnState,
47		summaryStatus: SessionStatus,
48		error?: { errorType: string; message: string; stack?: string },
49	): ISessionState {
50		if (!state.activeTurn || state.activeTurn.id !== turnId) {
51			return state;
52		}
53		const active = state.activeTurn;
54	
55		const toolCalls: (IToolCallCompletedState | IToolCallCancelledState)[] = [];
56		for (const tc of Object.values(active.toolCalls)) {
57			if (tc.status === ToolCallStatus.Completed || tc.status === ToolCallStatus.Cancelled) {
58				toolCalls.push(tc);
59			} else {
60				// Force non-terminal tool calls into cancelled state.
61				toolCalls.push({
62					status: ToolCallStatus.Cancelled,
63					...tcBase(tc),
64					invocationMessage: tc.status === ToolCallStatus.Streaming ? (tc.invocationMessage ?? '') : tc.invocationMessage,
65					toolInput: tc.status === ToolCallStatus.Streaming ? undefined : tc.toolInput,
66					reason: ToolCallCancellationReason.Skipped,
67				});
68			}
69		}
70	
71		const turn: ITurn = {
72			id: active.id,
73			userMessage: active.userMessage,
74			responseText: active.streamingText,
75			responseParts: active.responseParts,
76			toolCalls,
77			usage: active.usage,
78			state: turnState,
79			error,
80		};
81	
82		return {
83			...state,
84			turns: [...state.turns, turn],
85			activeTurn: undefined,
86			summary: { ...state.summary, status: summaryStatus, modifiedAt: Date.now() },
87		};
