74		const rawToken = connectionTokenIdx >= 0 ? argv[connectionTokenIdx + 1] : undefined;
75		const tokenFilePath = connectionTokenFileIdx >= 0 ? argv[connectionTokenFileIdx + 1] : undefined;
76	
77		let connectionToken: string | undefined;
78		if (withoutConnectionToken) {
79			if (rawToken !== undefined || tokenFilePath !== undefined) {
80				log('Error: --without-connection-token cannot be used with --connection-token or --connection-token-file');
81				process.exit(1);
82			}
83			connectionToken = undefined;
84		} else if (tokenFilePath !== undefined) {
