100			if (!connectionTokenRegex.test(rawToken)) {
101				log(`Error: The connection token '${rawToken}' does not adhere to the characters 0-9, a-z, A-Z, _, or -.`);
102				process.exit(1);
103			}
104			connectionToken = rawToken;
105		} else {
106			// Default: generate a random token (secure by default)
107			connectionToken = generateUuid();
108		}
109	
110		return { port, enableMockAgent, quiet, connectionToken };
